  '转炉煤气_燃气锅炉':  dict(CO=1.3, NOx=1.35, SO2=0,   VOC=0.05,  PM25=0.03, PM10=0.03, BC=0,   OC=0,   unit='g/m3'),
  '其它煤气_燃气锅炉':  dict(CO=1.3, NOx=1.35, SO2=0,   VOC=0.05,  PM25=0.03, PM10=0.03, BC=0,   OC=0,   unit='g/m3'),
  '天然气_燃气锅炉':    dict(CO=1.3, NOx=4.1,  SO2=0,   VOC=0.02,  PM25=0.03, PM10=0.03, BC=0,   OC=0,   unit='g/m3'),
  '液化天然气_燃气锅炉': dict(CO=0.36,NOx=3.74, SO2=0,   VOC=33,    PM25=0.17, PM10=0.17, BC=0.02,OC=0.05),
  '柴油_燃油锅炉':      dict(CO=0.6, NOx=7.4,  SO2=3,   VOC=0.13,  PM25=0.5,  PM10=0.5,  BC=0.01, OC=0.04),
  '燃料油_燃油锅炉':    dict(CO=0.6, NOx=10.06,SO2=20,  VOC=2.88,  PM25=0.62, PM10=0.85, BC=0.04, OC=0.01),
  '石油焦_燃油锅炉':    dict(CO=0.6, NOx=10.06,SO2=0,   VOC=33,    PM25=0.62, PM10=0.85, BC=0.04, OC=0.01),
  '原油_燃油锅炉':      dict(CO=0.6, NOx=7.24, SO2=0,   VOC=0.13,  PM25=0.62, PM10=0.85, BC=0.04, OC=0.01),
 },
 '热力生产和供应': {
  '煤炭_煤粉炉':        dict(CO=2,  NOx=8.85, SO2='MB', VOC=0.18,  PM25='MB', PM10='MB', BC='MB', OC='MB'),
  '煤炭_流化床炉':      dict(CO=2,  NOx=7.5,  SO2='MB', VOC=0.18,  PM25='MB', PM10='MB', BC='MB', OC='MB'),
  '煤炭_自动炉排层燃炉': dict(CO=8,  NOx=4,    SO2='MB', VOC=0.18,  PM25='MB', PM10='MB', BC='MB', OC='MB'),
  '天然气_燃气锅炉':    dict(CO=1.3,NOx=4.1,  SO2=0,   VOC=0.02,  PM25=0.03, PM10=0.03, BC=0,   OC=0,   unit='g/m3'),
 },
}

# 附录C 表C.1/C.2/C.3 燃煤源参数 (sr 硫分入底灰比例, ar 灰分入底灰比例, f25/f10 粒径分布, fbc/foc)
COAL_PARAM = {
 '电力生产': {
   '煤粉炉':         dict(sr=0.15, ar=0.25, f25=0.06, f10=0.23, fbc=0.002, foc=0.0),
