   '自动炉排层燃炉':  dict(sr=0.15, ar=0.85, f25=0.10, f10=0.33, fbc=0.002, foc=0.0),
 },
 '热力生产和供应': {
   '煤粉炉':         dict(sr=0.15, ar=0.25, f25=0.06, f10=0.23, fbc=0.002, foc=0.0),
   '流化床炉':       dict(sr=0.15, ar=0.44, f25=0.07, f10=0.29, fbc=0.002, foc=0.0),
   '自动炉排层燃炉':  dict(sr=0.15, ar=0.85, f25=0.10, f10=0.33, fbc=0.002, foc=0.0),
 },
}

# 附录A 表A.1 控制措施平均去除效率 (%) (so2, nox, pm25, pm25_10, bc, oc)
APPENDIX_A = {
 '烟气循环流化床法': (50, 0, 0, 0, 0, 0),
 '炉内喷钙法':       (50, 0, 0, 0, 0, 0),
 '石灰石/石膏法':    (80, 0, 57, 75, 57, 57),
 '双碱法':           (80, 0, 57, 75, 57, 57),
 '海水法':           (80, 0, 57, 75, 57, 57),
 '氧化镁法':         (80, 0, 57, 75, 57, 57),
 '氨法':             (80, 0, 57, 75, 57, 57),
 '密相干法':         (50, 0, 0, 0, 0, 0),
 '旋转喷雾干燥法':   (50, 0, 0, 0, 0, 0),
 '其他脱硫技术':     (40, 0, 0, 0, 0, 0),
 '低氮燃烧技术':     (0, 22, 0, 0, 0, 0),
 '选择性非催化还原法（SNCR）': (0, 30, 57, 75, 57, 57),
 '选择性催化还原法（SCR）':    (0, 42, 57, 75, 57, 57),
 '低氮燃烧技术+选择性非催化还原法': (0, 52, 0, 0, 0, 0),
 '低氮燃烧技术+选择性催化还原法':    (0, 64, 0, 0, 0, 0),
 '其他脱硝技术':     (0, 20, 0, 0, 0, 0),
 '湿式除尘法':       (20, 0, 50, 56.1, 50, 50),
 '普通静电除尘法':   (0, 0, 93, 98, 93, 93),
 '高效静电除尘法':   (0, 0, 96, 99, 96, 96),
 '袋式除尘法':       (0, 0, 94.5, 95, 94.5, 94.5),
 '电袋复合除尘法':   (0, 0, 96, 99, 96, 96),
 '机械式除尘法':     (0, 0, 10, 19.2, 10, 10),
 '多管旋风除尘法':   (0, 0, 10, 70, 10, 10),
 '其他除尘技术':     (0, 0, 10, 70, 10, 10),
 '重力沉降法':       (0, 0, 10, 70, 10, 10),
}

def map_measure(kind, tech):
    """处理工艺名称 -> 附录A 措施名 (keyword rules, order matters). None if tech unknown."""
    if tech is None or (isinstance(tech, float) and math.isnan(tech)):
        return None
    t = str(tech)
    if kind == 'SO2':
        if '石灰' in t or '石膏' in t: return '石灰石/石膏法'
        if '循环流化床' in t: return '烟气循环流化床法'
        if '喷钙' in t: return '炉内喷钙法'
        if '氨法' in t: return '氨法'
        if '氧化镁' in t: return '氧化镁法'
        if '海水' in t: return '海水法'
        if '双碱' in t: return '双碱法'
        if '电石渣' in t: return '石灰石/石膏法'
        return '其他脱硫技术'
    if kind == 'NOx':
        u = t.upper()
        if 'SNCR' in u and 'SCR' in u: return '选择性催化还原法（SCR）'
        if 'SCR' in u: return '选择性催化还原法（SCR）'
        if 'SNCR' in u: return '选择性非催化还原法（SNCR）'
        return '其他脱硝技术'
    if kind == 'PM':
        if '电袋' in t: return '电袋复合除尘法'
        if '高效静电' in t: return '高效静电除尘法'
        if '静电' in t: return '普通静电除尘法'
        if '袋式' in t or '布袋' in t: return '袋式除尘法'
        if '湿式' in t: return '湿式除尘法'
        if '旋风' in t: return '多管旋风除尘法'
        if '文丘里' in t: return '湿式除尘法'
        if '重力' in t: return '重力沉降法'
        if '惯性' in t: return '机械式除尘法'
        return '其他除尘技术'
    return None

POLLUTANTS = ['SO2', 'NOx', 'CO', 'VOC', 'PM2.5', 'PM10', 'BC', 'OC', 'NH3']

# ---------------------------------------------------------------- loading ----
print('loading inputs ...')
b102 = pd.read_excel(os.path.join(IN, '基102-2002_原始结构脱敏输入.xlsx'), sheet_name='Sheet1')
ctrl = pd.read_excel(os.path.join(IN, '基101-2002_原始结构脱敏输入.xlsx'), sheet_name='Sheet1')
with open(os.path.join(IN, 'source_identity_index.json'), encoding='utf-8') as f:
    idx = json.load(f)
src_by_row = {r['source_row']: r['source_id'] for r in idx['records']}
assert len(src_by_row) == len(b102), (len(src_by_row), len(b102))

b102['_row'] = b102.index + 2
b102['source_id'] = b102['_row'].map(src_by_row)
b102['行业类别代码_s'] = b102['行业类别代码'].astype(str).str.strip()

has_pow = b102['电站锅炉/燃气轮机编号'].notna()
has_ind = b102['工业锅炉编号'].notna()
assert (has_pow & has_ind).sum() == 0 and (~has_pow & ~has_ind).sum() == 0

# ---------------------------------------------------------------- decisions ----
def decide(row):
    if pd.notna(row['电站锅炉/燃气轮机编号']):
        return 'POWER', 'included', 'DEV_POWER_STATION_BOILER'
    if pd.notna(row['工业锅炉编号']):
        return 'BOILER', 'excluded_industrial_boiler', 'DEV_INDUSTRIAL_BOILER'
    return 'OUT_OF_SCOPE', 'excluded_non_combustion', 'DEV_NONE'

dec = b102.apply(decide, axis=1, result_type='expand')
b102['decided_target'] = dec[0]
b102['disposition'] = dec[1]
b102['reason_code'] = dec[2]

# --------------------------------------- control efficiency per enterprise ----
# 治理设施表: 按企业+排放口类型DZGL归集; 每污染物类型取 max(实际去除效率 或 附录A默认)
dz = ctrl[ctrl['对应的排放口代码'] == 'DZGL'].copy()
dz['ptype'] = dz['废气治理设施名称'].map({
    '脱硫（酸）设施': 'SO2', '脱硝设施': 'NOx', '除尘设施': 'PM',
    '挥发性有机物治理设施': 'VOC', '其他废气污染物治理设施': 'OTHER'})

def facility_eff(ptype, rep, tech):
    """return (eff, method) ; PM -> ((fine, coarse), method); None if unknown"""
    if pd.notna(rep):
        v = float(rep)
        if 0 <= v <= 100:
            return v, 'reported'
    m = map_measure(ptype, tech)
    if m is None:
        return None, None
    if ptype == 'SO2':
        return APPENDIX_A[m][0], m
    if ptype == 'NOx':
        return APPENDIX_A[m][1], m
    if ptype == 'PM':
        return (APPENDIX_A[m][2], APPENDIX_A[m][3]), m
    return None, None

ent_ctl = {}
for _, r in dz.iterrows():
    pt = r['ptype']
    if pt not in ('SO2', 'NOx', 'PM'):
        continue
    e = ent_ctl.setdefault(r['统一社会信用代码'], {})
    got = facility_eff(pt, r['去除效率（%）'], r['处理工艺名称'])
    if got[0] is None:
        if pt in e and e[pt].get('eff') is not None:
            continue          # keep best known
        e[pt] = {'eff': None, 'method': None}
        continue
    if pt == 'PM':
        eff_f, eff_c = got[0]
        cur = e.get(pt)
        if cur is None or cur.get('eff') is None or eff_f > cur['eff'][0]:
            e[pt] = {'eff': (eff_f, eff_c), 'method': got[1]}
    else:
        cur = e.get(pt)
        if cur is None or cur.get('eff') is None or got[0] > cur['eff']:
            e[pt] = {'eff': got[0], 'method': got[1]}

def source_controls(row):
    ent = row['统一社会信用代码']
    info = ent_ctl.get(ent, {})
    low_nox = (str(row['是否采用低氮燃烧技术']).strip() == '是')
    c = {}
    so = info.get('SO2')
    if so and so.get('eff') is not None:
        c['SO2'] = (so['eff'], so['method'])
    elif so:
        c['SO2'] = (None, 'unknown')
    else:
        c['SO2'] = (0.0, 'none')
    nx = info.get('NOx')
    if nx and nx.get('eff') is not None:
        c['NOx'] = (nx['eff'], nx['method'])
    elif nx:
        c['NOx'] = (None, 'unknown')
    elif low_nox:
        c['NOx'] = (22.0, '低氮燃烧技术')
    else:
        c['NOx'] = (0.0, 'none')
    pm = info.get('PM')
    if pm and pm.get('eff') is not None:
        c['PM'] = (pm['eff'][0], pm['eff'][1], pm['method'])
    elif pm:
        c['PM'] = (None, None, 'unknown')
    else:
        co = 0.0
        for key in ('SO2', 'NOx'):
            kv = c.get(key)
            if kv and kv[0] is not None and kv[1] in APPENDIX_A:
                co = max(co, APPENDIX_A[kv[1]][2])
        c['PM'] = (co, co, 'co_benefit') if co > 0 else (0.0, 0.0, 'none')
    c['CO'] = (0.0, 'none')
    c['VOC'] = (0.0, 'none')
    return c

# -------------------------------------------------------------- components ----
def fuel_components(row):
    comps = []
    f1 = str(row['燃料一类型']).strip()
    comps.append(('F1_' + f1, f1, float(row['燃料一消耗量']),
                  str(row['燃料一消耗量单位']).strip(), 'fuel1'))
    q2 = row['燃料二消耗量']
    if pd.notna(q2) and float(q2) > 0 and pd.notna(row['燃料二类型']):
        f2 = str(row['燃料二类型']).strip()
        comps.append(('F2_' + f2, f2, float(q2),
                      str(row['燃料二消耗量单位']).strip(), 'fuel2'))
    oth = row['其他燃料消耗总量（吨标准煤）']
    if pd.notna(oth) and float(oth) > 0:
        dupe = (str(row['燃料一消耗量单位']).strip() == '吨标准煤'
                and abs(float(oth) - float(row['燃料一消耗量'])) < 1e-9)
        if not dupe:
            comps.append(('F3_其他燃料', '其他燃料', float(oth), '吨标准煤', 'other'))
    return comps

def coal_tech(row):
    m = str(row['电站锅炉燃烧方式']).strip()
    if '煤粉' in m:
        return '煤粉炉'
    if '流化床' in m:
        return '流化床炉'
    return '自动炉排层燃炉'      # 层燃炉/链条炉/其他层燃炉/其他 -> 自动炉排层燃炉

def fuel_d1key(ftype):
    if ftype in ('原煤', '一般烟煤', '无烟煤', '褐煤', '煤制品'):
        return ('COAL', None)
    if ftype == '煤矸石（用于燃料）':
        return ('COAL_GANGUE', None)
    if ftype == '天然气':
        return ('GAS', '天然气_燃气锅炉')
    if ftype == '液化天然气':
        return ('GAS', '液化天然气_燃气锅炉')
    if ftype == '柴油':
        return ('OIL', '柴油_燃油锅炉')
    if ftype == '燃料油':
        return ('OIL', '燃料油_燃油锅炉')
    if ftype == '石油焦（用于燃料）':
        return ('OIL', '石油焦_燃油锅炉')
    if ftype == '原油':
        return ('OIL', '原油_燃油锅炉')
    if ftype in ('焦炉煤气', '高炉煤气', '转炉煤气', '其它煤气', '其他煤气'):
        k = '其它煤气_燃气锅炉' if ftype in ('其它煤气', '其他煤气') else f'{ftype}_燃气锅炉'
        return ('GAS', k)
    return (None, None)          # 生物燃料/城市生活垃圾/其他燃料/工业废料 etc.

def component_ef25(ftype, sector, tech, A):
    """PM2.5产生系数 (g/kg or g/m3) for a component, for the PM10 fine/coarse split."""
    if ftype in ('原煤', '一般烟煤', '无烟煤', '褐煤', '煤制品'):
        if A is None:
            return None
        cp = COAL_PARAM[sector][tech]
        return 1000.0 * (A / 100.0) * (1 - cp['ar']) * cp['f25']
    if ftype == '天然气':
        return 0.03
    if ftype == '液化天然气':
        return 0.17
    if ftype == '柴油':
        return 0.5
    if ftype == '燃料油':
        return 0.62
    if ftype in ('焦炉煤气', '高炉煤气', '转炉煤气', '其它煤气', '其他煤气'):
        return 0.03
    return None

def sector_of(row):
    return '热力生产和供应' if row['行业类别代码_s'] == '4430' else '电力生产'

# ------------------------------------------------------------ emission calc ----
def calc_source(row, row_state):
    """returns list of per-pollutant item dicts for a POWER source"""
    sector = sector_of(row)
    comps = fuel_components(row)
    ctl = source_controls(row)
    capacity = row['对应机组装机容量（万千瓦）']
    capacity = float(capacity) if pd.notna(capacity) else None
    tech = coal_tech(row)

    # per-component EF resolution for the 8 combustion pollutants
    comp_ef = {}     # cid -> {pollutant: (efv, unit_mode, role)}
    comp_missing = {}  # cid -> reason (unfactorable fuel) or None
    for cid, ftype, qty, unit, role in comps:
        kind, d1key = fuel_d1key(ftype)
        spec = None
        if d1key is not None:
            spec = D1.get(sector, {}).get(d1key) or D1.get('电力生产', {}).get(d1key)
        if spec is None:
            comp_missing[cid] = 'FUEL_EF_MISSING'
            continue
        if unit not in ('吨', '万立方米'):
            comp_missing[cid] = 'UNIT_INVALID'
            continue
        unit_mode = 'g/m3' if spec.get('unit') == 'g/m3' else 'g/kg'
        S = row['燃料一平均收到基含硫量'] if role == 'fuel1' else row['燃料二平均收到基含硫量']
        A = row['燃料一平均收到基灰分（%）'] if role == 'fuel1' else row['燃料二平均收到基灰分（%）']
        mb_ok = True
        ef = {}
        for p in ('CO', 'NOx', 'SO2', 'VOC', 'PM2.5', 'PM10', 'BC', 'OC'):
            v = spec[p]
            if v == 'MB':
                if p == 'SO2':
                    if pd.isna(S):
                        comp_missing[cid] = 'SULFUR_MISSING'; mb_ok = False; break
                    v = 20.0 * float(S) * (1 - COAL_PARAM[sector][tech]['sr'])
                else:
                    if pd.isna(A):
                        comp_missing[cid] = 'ASH_MISSING'; mb_ok = False; break
                    cp = COAL_PARAM[sector][tech]
                    pm25 = 1000.0 * (float(A) / 100.0) * (1 - cp['ar']) * cp['f25']
                    if p == 'PM2.5':
                        v = pm25
                    elif p == 'PM10':
                        v = 1000.0 * (float(A) / 100.0) * (1 - cp['ar']) * cp['f10']
                    elif p == 'BC':
                        v = pm25 * cp['fbc']
                    elif p == 'OC':
                        v = pm25 * cp['foc']
            elif p == 'NOx' and v == 'cap':
                v = 8.96 if capacity is None else (7.21 if capacity >= 300
                                                   else (8.19 if capacity > 100 else 8.96))
            ef[p] = float(v)
        if mb_ok:
            comp_ef[cid] = (ef, unit_mode, role, spec)

    # per-pollutant assembly
    results = []
    for p in POLLUTANTS:
        if p == 'NH3':
            results.append(dict(pollutant=p, status='not_involved',
                                reason='NH3_NOT_IN_POWER_METHOD', gen=None, emi=None,
                                method='', stdref='T/CSES 144-2024 §7/表D.1 无NH3产生系数',
                                act=[], par=[], ctr=[]))
            continue
        cids = [c[0] for c in comps]
        status, reason = 'calculated', 'OK'
        for cid in cids:
            if cid in comp_missing:
                status, reason = 'information_insufficient', comp_missing[cid]
                break
        # control
        if p in ('PM2.5', 'BC', 'OC'):
            eff_f, eff_c, cm = ctl['PM']
            eff = eff_f
        elif p == 'PM10':
            eff_f, eff_c, cm = ctl['PM']
            eff = None
        else:
            eff, cm = ctl[p]
            eff_f = eff_c = eff
        if eff is None and p == 'PM10':
            eff_f, eff_c = ctl['PM'][0], ctl['PM'][1]
        if status == 'calculated' and (eff is None if p != 'PM10' else ctl['PM'][0] is None):
            status, reason = 'information_insufficient', 'CONTROL_EFF_UNKNOWN'

        # build arrays (aligned by component order)
        act, par, ctr = [], [], []
        for cid, ftype, qty, unit, role in comps:
            act.append({'component_id': cid, 'value': qty, 'unit': unit})
            if cid in comp_ef:
                ef, unit_mode, role_, spec = comp_ef[cid]
                par.append({'component_id': cid, 'parameter_id': 'EF_' + p,
                            'mode': 'material_balance' if spec[p] == 'MB' else
                                    ('table_D1_capacity' if (p == 'NOx' and spec['NOx'] == 'cap')
                                     else ('table_D1_gas' if unit_mode == 'g/m3' else 'table_D1')),
                            'value': round(ef[p], 6), 'unit': unit_mode})
                if status == 'calculated' and p == 'PM10':
                    # PM10 emission uses fine/coarse split
                    A = row['燃料一平均收到基灰分（%）'] if role == 'fuel1' else row['燃料二平均收到基灰分（%）']
                    ef25 = component_ef25(ftype, sector, tech, float(A) if pd.notna(A) else None)
                    if ef25 is not None:
                        par.append({'component_id': cid, 'parameter_id': 'EF_PM25_SPLIT',
                                    'mode': 'material_balance', 'value': round(ef25, 6),
                                    'unit': unit_mode})
                if status == 'calculated' and p in ('SO2', 'PM2.5', 'PM10', 'BC', 'OC'):
                    if spec[p] == 'MB':
                        key = 'S' if p == 'SO2' else 'ASH'
                        val = row['燃料一平均收到基含硫量'] if (role == 'fuel1' and p == 'SO2') else \
                              (row['燃料二平均收到基含硫量'] if (role == 'fuel2' and p == 'SO2') else
                               (row['燃料一平均收到基灰分（%）'] if role == 'fuel1' else row['燃料二平均收到基灰分（%）']))
                        par.append({'component_id': cid, 'parameter_id': key,
                                    'mode': 'input', 'value': round(float(val), 6), 'unit': '%'})
            else:
                par.append({'component_id': cid, 'parameter_id': 'EF_' + p,
                            'mode': 'missing', 'value': '', 'unit': ''})
            if status == 'calculated':
                ctr.append({'component_id': cid, 'method': cm,
                            'efficiency': ('' if p == 'PM10' else eff),
                            'fine_efficiency': eff_f, 'coarse_efficiency': eff_c})
            else:
                ctr.append({'component_id': cid, 'method': ('unknown' if reason == 'CONTROL_EFF_UNKNOWN' else 'not_applicable'),
                            'efficiency': '', 'fine_efficiency': '', 'coarse_efficiency': ''})

        if status != 'calculated':
            results.append(dict(pollutant=p, status=status, reason=reason,
                                gen=None, emi=None, method='', stdref='',
                                act=act, par=par, ctr=ctr))
            continue
        # compute generation / emission
        gen, emi = 0.0, 0.0
        stdrefs = set()
        for cid, ftype, qty, unit, role in comps:
            ef, unit_mode, role_, spec = comp_ef[cid]
            stdrefs.add(f'表D.1 {sector} {spec_fuel_label(ftype, role)}')
            if unit_mode == 'g/m3':
                g = qty * ef[p] / 100.0
            else:
                g = qty * ef[p] / 1000.0
            gen += g
            if p == 'PM10':
                A = row['燃料一平均收到基灰分（%）'] if role == 'fuel1' else row['燃料二平均收到基灰分（%）']
                ef25 = component_ef25(ftype, sector, tech, float(A) if pd.notna(A) else None)
                g25 = qty * ef25 / (100.0 if unit_mode == 'g/m3' else 1000.0)
                emi += g25 * (1 - eff_f / 100.0) + (g - g25) * (1 - eff_c / 100.0)
            else:
                emi += g
        if p != 'PM10':
            emi = gen * (1 - eff / 100.0)
        results.append(dict(pollutant=p, status='calculated', reason='OK',
                            gen=round(gen, 6), emi=round(emi, 6),
                            method='产排污系数法 E=A×EF×(1-η)',
                            stdref='T/CSES 144-2024 §7.2, ' + '; '.join(sorted(stdrefs)),
                            act=act, par=par, ctr=ctr))
    return results

